const l={render(){const i=document.createElement("div"),t=[{label:"Avatar Circle",desc:"Brand logo or photo in a circle &mdash; locked top-left on every post",eg:"MPowerMyBiz logo in a dark circle"},{label:"Display Name",desc:"Name in bold white with verified checkmark &mdash; consistent every time",eg:"MPowerMyBiz &#10003;"},{label:"@handle",desc:"Social handle in muted grey directly below the name",eg:"@mpowermybiz"},{label:"Category Pill Badge",desc:"Red pill Claude picks to match each post&rsquo;s topic &mdash; changes every post",eg:"Real Talk &nbsp;&middot;&nbsp; AI Tools &nbsp;&middot;&nbsp; Business Growth"},{label:"Headline Text",desc:"The main message &mdash; large, bold, white, auto-wraps to fit any length",eg:"&ldquo;Your Calendar Is Full. Your Work Isn&rsquo;t Done.&rdquo;"},{label:"Sub-headline",desc:"Punchy supporting line &mdash; adds context, tension, or a CTA",eg:"&ldquo;AI clears the noise. You own the wins.&rdquo;"}],r=t.map(function(e,a){return'<div style="display:flex;gap:11px;align-items:flex-start;padding:10px 0;'+(a===t.length-1?"":"border-bottom:1px solid #f0f0f0;")+'"><div style="width:22px;height:22px;border-radius:50%;background:#CC0000;color:#fff;font-size:0.68rem;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px;">'+(a+1)+'</div><div style="flex:1;min-width:0;"><div style="font-weight:700;color:#1A1A1A;font-size:0.85rem;margin-bottom:1px;">'+e.label+'</div><div style="color:#666;font-size:0.77rem;line-height:1.5;margin-bottom:3px;">'+e.desc+'</div><div style="font-size:0.72rem;font-weight:600;color:#CC0000;"><span style="color:#bbb;font-weight:400;margin-right:3px;">e.g.</span>'+e.eg+"</div></div></div>"}).join(""),n=["Pure black background on every post","Same avatar, name &amp; handle placement","Red accent color stays constant","Instantly recognizable as your brand"],s=["Category pill matches each post&rsquo;s topic","Headline &amp; sub-headline are AI-generated","Layout stays locked &mdash; only copy swaps","Fresh content, zero manual design work"],d=function(e,a){return e.map(function(o){return'<div style="display:flex;gap:9px;align-items:flex-start;padding:4px 0;"><div style="width:6px;height:6px;border-radius:50%;background:'+a+';flex-shrink:0;margin-top:7px;"></div><span style="color:#555;font-size:0.83rem;line-height:1.6;">'+o+"</span></div>"}).join("")};return i.innerHTML='\n      <style data-edit-path="style.0">\n        @media(max-width:640px){\n          .ga-main{flex-direction:column!important;}\n          .ga-img-col{max-width:100%!important;min-width:0!important;}\n          .ga-zones-col{min-width:0!important;}\n          .ga-brand{grid-template-columns:1fr!important;}\n        }\n      </style>\n      <div style="max-width:860px;margin:0 auto;padding:28px clamp(14px,4vw,24px);font-family:sans-serif;">\n\n        <div style="height:4px;background:linear-gradient(90deg,#CC0000 0%,#1A1A1A 100%);border-radius:2px;margin-bottom:24px;"></div>\n\n        <div style="margin-bottom:10px;" data-edit-path="div.0/div.1">\n          <span style="background:#fff0f0;color:#CC0000;font-size:0.7rem;font-weight:800;padding:4px 13px;border-radius:20px;letter-spacing:1.2px;" data-edit-path="div.0/div.1/span.0">GRAPHIC ANATOMY</span>\n        </div>\n\n        <h2 style="font-size:clamp(1.35rem,5vw,1.9rem);font-weight:800;color:#1A1A1A;margin:0 0 8px;line-height:1.2;" data-edit-path="div.0/h2.0">What Goes Into Every Graphic</h2>\n        <p style="color:#666;font-size:0.92rem;line-height:1.7;margin:0 0 22px;" data-edit-path="div.0/p.0">Every post has the same 6 zones &mdash; auto-generated by Claude Code every single time. Here&rsquo;s a real MPowerMyBiz graphic with each zone called out.</p>\n\n        <!-- ── Two-column: image left, zones right ── -->\n        <div class="ga-main" style="display:flex;gap:28px;align-items:flex-start;margin-bottom:28px;">\n\n          <!-- Left: real graphic -->\n          <div class="ga-img-col" style="flex:0 0 340px;max-width:340px;" data-edit-path="div.0/ga-main.0/ga-img-col.0">\n            <div style="font-size:0.63rem;font-weight:800;letter-spacing:1.5px;color:#aaa;margin-bottom:10px;text-transform:uppercase;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.0">Real Auto-Generated Output</div>\n            <div style="border-radius:12px;overflow:hidden;box-shadow:0 6px 28px rgba(0,0,0,0.22);">\n              <img src="./course/assets/images/linkedin-graphic-example.png"\n                alt="Real MPowerMyBiz LinkedIn graphic showing avatar circle, display name with verified badge, @mpowermybiz handle, Real Talk pill badge, headline and sub-headline on black background"\n                style="width:100%;display:block;" />\n            </div>\n            <!-- ── Social links — 3 across, always one row ── -->\n            <div style="margin-top:12px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2">\n              <div style="font-size:0.63rem;font-weight:800;letter-spacing:1.2px;color:#aaa;text-transform:uppercase;margin-bottom:8px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.0">See it live</div>\n              <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1">\n\n                <!-- LinkedIn -->\n                <a href="https://www.linkedin.com/company/110442998/" target="_blank" rel="noopener"\n                  style="display:flex;flex-direction:column;align-items:center;gap:5px;text-decoration:none;background:#e8f0fe;border:1px solid #c5d8f8;padding:8px 6px;border-radius:8px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.0">\n                  <img src="https://www.google.com/s2/favicons?domain=linkedin.com&sz=64" style="width:28px;height:28px;display:block;border-radius:6px;" alt="LinkedIn" />\n                  <span style="font-size:0.72rem;font-weight:700;color:#0A66C2;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.0/span.0">LinkedIn &#8599;</span>\n                </a>\n\n                <!-- Instagram -->\n                <a href="https://www.instagram.com/mpowermybiz/" target="_blank" rel="noopener"\n                  style="display:flex;flex-direction:column;align-items:center;gap:5px;text-decoration:none;background:#fce4ec;border:1px solid #f4b8cc;padding:8px 6px;border-radius:8px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.1">\n                  <img src="https://www.google.com/s2/favicons?domain=instagram.com&sz=64" style="width:28px;height:28px;display:block;border-radius:6px;" alt="Instagram" />\n                  <span style="font-size:0.72rem;font-weight:700;color:#C13584;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.1/span.0">Instagram &#8599;</span>\n                </a>\n\n                <!-- Facebook -->\n                <a href="https://www.facebook.com/profile.php?id=61550458567613" target="_blank" rel="noopener"\n                  style="display:flex;flex-direction:column;align-items:center;gap:5px;text-decoration:none;background:#e3f2fd;border:1px solid #b3d4f5;padding:8px 6px;border-radius:8px;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.2">\n                  <img src="https://www.google.com/s2/favicons?domain=facebook.com&sz=64" style="width:28px;height:28px;display:block;border-radius:6px;" alt="Facebook" />\n                  <span style="font-size:0.72rem;font-weight:700;color:#1877F2;" data-edit-path="div.0/ga-main.0/ga-img-col.0/div.2/div.1/a.2/span.0">Facebook &#8599;</span>\n                </a>\n\n              </div>\n            </div>\n          </div>\n\n          <!-- Right: zone breakdown -->\n          <div class="ga-zones-col" style="flex:1;min-width:0;">\n            <div style="font-size:0.63rem;font-weight:800;letter-spacing:1.5px;color:#aaa;margin-bottom:10px;text-transform:uppercase;" data-edit-path="div.0/ga-main.0/ga-zones-col.0/div.0">The 6 Zones &mdash; Always the Same</div>\n            <div style="background:#fafafa;border:1px solid #efefef;border-radius:10px;padding:4px 16px;">\n              '.concat(r,'\n            </div>\n          </div>\n\n        </div>\n\n        <!-- ── Full-width brand section ── -->\n        <div style="border-top:1px solid #ebebeb;padding-top:22px;margin-bottom:24px;">\n          <div style="font-size:0.67rem;font-weight:800;letter-spacing:1.5px;color:#aaa;margin-bottom:16px;text-transform:uppercase;" data-edit-path="div.0/div.2/div.0">Fixed vs. Fresh &mdash; How the Brand Works</div>\n          <div class="ga-brand" style="display:grid;grid-template-columns:1fr 1fr;gap:24px;">\n            <div style="background:#f9f9f9;border-radius:10px;padding:16px 18px;">\n              <div style="font-size:0.65rem;font-weight:800;letter-spacing:1.5px;color:#888;margin-bottom:8px;text-transform:uppercase;" data-edit-path="div.0/div.2/ga-brand.0/div.0/div.0">Always Fixed</div>\n              <div style="width:28px;height:3px;background:#1A1A1A;border-radius:2px;margin-bottom:10px;"></div>\n              ').concat(d(n,"#1A1A1A"),'\n            </div>\n            <div style="background:#fff5f5;border-radius:10px;padding:16px 18px;">\n              <div style="font-size:0.65rem;font-weight:800;letter-spacing:1.5px;color:#CC0000;margin-bottom:8px;text-transform:uppercase;" data-edit-path="div.0/div.2/ga-brand.0/div.1/div.0">Claude Generates Fresh</div>\n              <div style="width:28px;height:3px;background:#CC0000;border-radius:2px;margin-bottom:10px;"></div>\n              ').concat(d(s,"#CC0000"),'\n            </div>\n          </div>\n        </div>\n\n        <!-- ── CTA bar ── -->\n        <div style="display:flex;align-items:center;gap:14px;padding:16px 20px;background:#1A1A1A;border-radius:10px;margin-bottom:20px;" data-edit-path="div.0/div.3">\n          <div style="width:3px;height:36px;background:#CC0000;border-radius:2px;flex-shrink:0;"></div>\n          <p style="margin:0;font-size:0.93rem;font-weight:700;color:#fff;line-height:1.6;" data-edit-path="div.0/div.3/p.0">You define the style once in your Claude Code prompt &mdash; every graphic that follows locks to it automatically.</p>\n        </div>\n\n        <!-- ── Tip 1: Imgur ── -->\n        <div style="display:flex;gap:12px;align-items:flex-start;background:#fffbf0;border-left:3px solid #f5a623;border-radius:0 8px 8px 0;padding:13px 15px;margin-bottom:12px;" data-edit-path="div.0/div.4">\n          <span style="font-size:0.9rem;flex-shrink:0;margin-top:1px;" data-edit-path="div.0/div.4/span.0">&#128161;</span>\n          <div style="font-size:0.82rem;color:#7a5900;line-height:1.75;" data-edit-path="div.0/div.4/div.0">\n            <strong data-edit-path="div.0/div.4/div.0/strong.0">Use Imgur for image hosting &mdash; tell Claude explicitly.</strong> When Claude Code builds your graphic script, it may try different image hosting options. <a href="https://imgur.com" target="_blank" rel="noopener" style="color:#7a5900;font-weight:700;" data-edit-path="div.0/div.4/div.0/a.0">Imgur</a> is the easiest and most reliable &mdash; no downloading, no saving to Google Drive, just a clean public URL that plugs straight into the webhook. Make sure your Claude Code instructions specifically say to use Imgur for image uploads. It&rsquo;ll be included, but calling it out keeps everything consistent.\n          </div>\n        </div>\n\n        <!-- ── Tip 2: Screenshots ── -->\n        <div style="display:flex;gap:12px;align-items:flex-start;background:#fffbf0;border-left:3px solid #f5a623;border-radius:0 8px 8px 0;padding:13px 15px;margin-bottom:12px;" data-edit-path="div.0/div.5">\n          <span style="font-size:0.9rem;flex-shrink:0;margin-top:1px;" data-edit-path="div.0/div.5/span.0">&#128247;</span>\n          <div style="font-size:0.82rem;color:#7a5900;line-height:1.75;" data-edit-path="div.0/div.5/div.0">\n            <strong data-edit-path="div.0/div.5/div.0/strong.0">Give Claude a screenshot of your graphic so it can connect the pieces.</strong> The example above is a real MPowerMyBiz auto-generated post. When giving Claude Code instructions, attach a screenshot of this graphic (or your own branded version) so it has a visual reference. Seeing the layout, colors, and structure helps Claude generate something much closer to what you actually want &mdash; faster and with less back-and-forth.\n          </div>\n        </div>\n\n        <!-- ── Tip 3: Trial & error ── -->\n        <div style="display:flex;gap:12px;align-items:flex-start;background:#fffbf0;border-left:3px solid #f5a623;border-radius:0 8px 8px 0;padding:13px 15px;" data-edit-path="div.0/div.6">\n          <span style="font-size:0.9rem;flex-shrink:0;margin-top:1px;" data-edit-path="div.0/div.6/span.0">&#128161;</span>\n          <div style="font-size:0.82rem;color:#7a5900;line-height:1.75;" data-edit-path="div.0/div.6/div.0">\n            <strong data-edit-path="div.0/div.6/div.0/strong.0">It won&rsquo;t be perfect the first time &mdash; and that&rsquo;s completely normal.</strong> Expect some trial and error when generating your branded graphic. When something breaks or looks off, paste the error or a screenshot straight back to Claude Code and it will diagnose and fix it. Iteration is part of the process.\n          </div>\n        </div>\n\n      </div>'),i}};export{l as slide};
